<script setup lang="ts">
import {ref,computed} from 'vue';import type {EChartsOption} from 'echarts';import type {TableColumnData} from '@arco-design/web-vue';import PageHeader from '../components/PageHeader.vue';import StatChart from '../components/StatChart.vue';import GiTable from '../components/GiTable.vue';import {api} from '../api/console';import {useResource} from '../composables/useResource';
const period=ref('day');const {data,loading,error,refresh}=useResource(()=>api.aiUsage(period.value));void refresh();
const chart=computed<EChartsOption>(()=>({animation:false,color:['#42695a'],tooltip:{trigger:'axis'},grid:{left:40,right:20,top:20,bottom:35},xAxis:{type:'category',data:data.value?.trend.map(t=>t.period)},yAxis:{type:'value',minInterval:1},series:[{name:'调用次数',type:'bar',barMaxWidth:25,data:data.value?.trend.map(t=>t.calls)}]}));
const columns:TableColumnData[]=[{title:'调用 ID',dataIndex:'id',width:220},{title:'功能',dataIndex:'feature'},{title:'模型',dataIndex:'model'},{title:'结果',dataIndex:'status'},{title:'输入 Token',dataIndex:'inputTokens'},{title:'输出 Token',dataIndex:'outputTokens'},{title:'耗时 ms',dataIndex:'durationMs'},{title:'估算成本 USD',slotName:'cost'},{title:'调用时间',slotName:'time',width:180}];
const load=api.aiCalls;
</script>
<template><page-header title="AI 用量与成本" description="汇总真实上游调用回执，费用按模型配置单价估算。"><a-radio-group v-model="period" type="button" @change="refresh"><a-radio value="day">按日</a-radio><a-radio value="week">按周</a-radio><a-radio value="month">按月</a-radio></a-radio-group><a-button @click="refresh">刷新</a-button></page-header><a-alert v-if="error" type="error">{{ error }}</a-alert><a-spin :loading="loading" class="block"><template v-if="data"><div class="metrics-grid"><article class="surface metric"><p>最近 30 天调用</p><strong>{{ data.totals.calls }}</strong><span>含备用模型尝试</span></article><article class="surface metric"><p>输入 / 输出 Token</p><strong>{{ data.totals.inputTokens??'—' }} / {{ data.totals.outputTokens??'—' }}</strong><span>仅包含返回 usage 的调用</span></article><article class="surface metric"><p>已知部分成本 USD</p><strong>{{ data.totals.costMicroUsd==null?'—':'$'+(data.totals.costMicroUsd/1000000).toFixed(4) }}</strong><span>{{ data.totals.pricedCalls }} / {{ data.totals.calls }} 次可估价</span></article><article class="surface metric"><p>上游调用成功率</p><strong>{{ data.totals.calls?((data.totals.successes??0)/data.totals.calls*100).toFixed(1)+'%':'—' }}</strong><span>平均 {{ data.totals.averageDurationMs?.toFixed(0)??'—' }} ms</span></article></div><a-alert class="notice">{{ data.integration }}</a-alert><section class="surface chart-panel"><h2>调用趋势</h2><stat-chart v-if="data.trend.length" :option="chart" label="AI 调用量趋势"/><a-empty v-else description="尚无上游调用记录"/></section></template></a-spin><page-header title="调用日志" description="仅保存模型、状态、Token 与耗时，不保存用户输入与模型输出。"/><gi-table :columns="columns" :load="load"><template #cost="{record}">{{ record.costMicroUsd==null?'未知':'$'+(record.costMicroUsd/1000000).toFixed(6) }}</template><template #time="{record}">{{ new Date(record.createdAt*1000).toLocaleString('zh-CN') }}</template></gi-table></template>
